#define SOUNIO_CLDR_GRAPH_ORACLE_NO_MAIN
#include "cldr_graph_oracle.cpp"
int main(int argc,char**argv){try{if(argc!=3)return 64;g_oracle_versions();cldr_input_versions(argv[1],argv[2]);Registry r(argv[1]);Fractional f(fs::path(argv[1])/"common/uca/FractionalUCA.txt");Fnormalize n(argv[2]);auto id=r.resolve("root","standard");Fbuilder b(f,n);b.apply(r,id);Fseq left{0x418,0x345,0x306},right{0x48b};b.lookup(n.nfd(left));b.lookup(n.nfd(right));Gprepared p(b);auto a=g_key(b,left,p),z=g_key(b,right,p);std::cout<<"ORIGINAL_LEFT "<<display(left)<<" ORIGINAL_RIGHT "<<display(right)<<"\nNFD_LEFT "<<display(n.nfd(left))<<"\nCPP_NFD_ORDER "<<(a<z?-1:z<a?1:0)<<"\n";auto c=g_compile(r.entries[id]);for(auto mode:{UCOL_OFF,UCOL_ON}){UErrorCode e=U_ZERO_ERROR;ucol_setAttribute(c,UCOL_NORMALIZATION_MODE,mode,&e);if(U_FAILURE(e))bad("normalization probe option");auto raw_left=g_icu_key(c,left),raw_right=g_icu_key(c,right);auto norm_left=g_icu_key(c,n.nfd(left));std::cout<<"ICU_NORMALIZATION "<<(mode==UCOL_ON?"ON":"OFF")<<" ORIGINAL_ORDER "<<(raw_left<raw_right?-1:raw_right<raw_left?1:0)<<" NFD_CONTROL_ORDER "<<(norm_left<raw_right?-1:raw_right<norm_left?1:0)<<"\n";}ucol_close(c);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
